const { env } = await import('node:process');
if (!env.DOC_JSON) { throw new Error('Missing DOC_JSON'); }
let doc;
try { doc = JSON.parse(env.DOC_JSON); } catch (e) { throw new Error('Invalid JSON in DOC_JSON'); }
globalThis.doc = doc;

const mod = await import('@stroc/pdf');
const { toPdf } = mod;
const bytes = await toPdf(globalThis.doc, { pageSize: 'A4' });
const { Buffer } = await import('node:buffer');
globalThis.pdfBase64 = Buffer.from(bytes).toString('base64');
